import { useMemo, useRef, useState } from 'react'
import type { ComponentType, FormEvent, ReactNode, CSSProperties } from 'react'
import {
  ArrowDownToLine, ArrowUpFromLine, BarChart3, Bell, Box, Calculator, CalendarDays, Check, ChevronDown,
  CircleHelp, ClipboardList, CreditCard, DatabaseBackup, FileBarChart, FileText, Filter, HelpCircle, Home,
  LayoutGrid, LogOut, Menu, MoreHorizontal, Package, Palette, Plus, Printer, ReceiptText, Search, Settings,
  ShieldCheck, ShoppingCart, SlidersHorizontal, Sparkles, Store, Tag, Trash2, TrendingUp, Truck, UserPlus,
  Users, WalletCards, X, Zap
} from 'lucide-react'
import { useAppStore } from './store'
import type { Business, Product } from './types'
import { formatMoney, formatNumber, parseMoney } from './lib/money'

type Icon = ComponentType<{ size?: number; strokeWidth?: number; className?: string }>
type Page = 'dashboard' | 'pos' | 'products' | 'inventory' | 'sales' | 'purchases' | 'customers' | 'suppliers' | 'expenses' | 'reports' | 'users' | 'settings' | 'help'

const nav: { id: Page; label: string; icon: Icon }[] = [
  { id: 'dashboard', label: 'لوحة التحكم', icon: Home },
  { id: 'pos', label: 'نقطة البيع', icon: Calculator },
  { id: 'products', label: 'المنتجات', icon: Package },
  { id: 'inventory', label: 'المخزون', icon: Box },
  { id: 'sales', label: 'المبيعات', icon: ReceiptText },
  { id: 'purchases', label: 'المشتريات', icon: ClipboardList },
  { id: 'customers', label: 'العملاء والديون', icon: Users },
  { id: 'suppliers', label: 'الموردون', icon: Truck },
  { id: 'expenses', label: 'المصروفات', icon: WalletCards },
  { id: 'reports', label: 'التقارير', icon: FileBarChart },
]

function App() {
  const { setupComplete, business } = useAppStore()
  const [page, setPage] = useState<Page>('dashboard')
  const [showMobileNav, setShowMobileNav] = useState(false)
  const [toast, setToast] = useState('')
  const go = (next: Page) => { setPage(next); setShowMobileNav(false) }
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2600) }

  if (!setupComplete) return <SetupWizard />
  return <div className="app" dir="rtl" style={{ '--primary': business.primaryColor } as CSSProperties}>
    <Sidebar page={page} onNavigate={go} open={showMobileNav} onClose={() => setShowMobileNav(false)} />
    <main className="main-shell">
      <header className="topbar">
        <div className="topbar-start"><button className="icon-button mobile-menu" onClick={() => setShowMobileNav(true)}><Menu size={20} /></button><div className="offline-pill"><span className="online-dot" /> يعمل بدون إنترنت</div></div>
        <div className="topbar-actions"><button className="icon-button notification"><Bell size={19} /><span /></button><div className="top-user"><div className="avatar small">ط</div><div><b>طارق العمامي</b><small>مدير النظام</small></div><ChevronDown size={15} /></div></div>
      </header>
      <div className="page-wrap">
        <PageHeader page={page} onNavigate={go} />
        {page === 'dashboard' && <Dashboard onNavigate={go} />}
        {page === 'pos' && <POS notify={notify} />}
        {page === 'products' && <Products notify={notify} />}
        {page === 'inventory' && <Inventory notify={notify} />}
        {page === 'sales' && <Sales />}
        {page === 'purchases' && <Purchases notify={notify} />}
        {page === 'customers' && <Customers notify={notify} />}
        {page === 'suppliers' && <Suppliers />}
        {page === 'expenses' && <Expenses notify={notify} />}
        {page === 'reports' && <Reports />}
        {page === 'users' && <UsersPage />}
        {page === 'settings' && <SettingsPage notify={notify} />}
        {page === 'help' && <Help />}
      </div>
    </main>
    {toast && <div className="toast"><Check size={17} /> {toast}</div>}
  </div>
}

function Sidebar({ page, onNavigate, open, onClose }: { page: Page; onNavigate: (p: Page) => void; open: boolean; onClose: () => void }) {
  const business = useAppStore((s) => s.business)
  return <><div className={`sidebar-overlay ${open ? 'show' : ''}`} onClick={onClose} /><aside className={`sidebar ${open ? 'open' : ''}`}>
    <div className="brand"><div className="brand-mark"><ScaleIcon /></div><div><strong>Dukkan</strong><span>إدارة أعمالك بذكاء</span></div><button className="icon-button close-sidebar" onClick={onClose}><X size={18} /></button></div>
    <div className="business-mini"><div className="business-logo">{business.logo ? <img src={business.logo} /> : <Store size={19} />}</div><div><b>{business.name}</b><small>{business.type}</small></div><MoreHorizontal size={17} /></div>
    <div className="nav-label">الرئيسية</div>
    <nav>{nav.slice(0, 2).map((item) => <NavItem key={item.id} item={item} active={page === item.id} onNavigate={onNavigate} />)}</nav>
    <div className="nav-label">إدارة النشاط</div>
    <nav>{nav.slice(2).map((item) => <NavItem key={item.id} item={item} active={page === item.id} onNavigate={onNavigate} />)}</nav>
    <div className="nav-label">النظام</div>
    <nav>
      <NavItem item={{ id: 'users', label: 'المستخدمون والصلاحيات', icon: ShieldCheck }} active={page === 'users'} onNavigate={onNavigate} />
      <NavItem item={{ id: 'settings', label: 'الإعدادات', icon: Settings }} active={page === 'settings'} onNavigate={onNavigate} />
      <NavItem item={{ id: 'help', label: 'مركز المساعدة', icon: CircleHelp }} active={page === 'help'} onNavigate={onNavigate} />
    </nav>
    <div className="sidebar-footer"><div className="backup-hint"><DatabaseBackup size={18} /><div><b>نسخة احتياطية</b><span>آخر نسخة: اليوم 09:10 ص</span></div><ArrowUpFromLine size={15} /></div><div className="version">Dukkan <span>v0.1.0</span></div></div>
  </aside></>
}

function ScaleIcon() { return <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M12 3v17M5 20h14M4 7h16M7 7l-3 6a3 3 0 0 0 6 0L7 7Zm10 0-3 6a3 3 0 0 0 6 0l-3-6Z" /></svg> }
function NavItem({ item, active, onNavigate }: { item: { id: Page; label: string; icon: Icon }; active: boolean; onNavigate: (p: Page) => void }) { const Icon = item.icon; return <button className={`nav-item ${active ? 'active' : ''}`} onClick={() => onNavigate(item.id)}><Icon size={18} strokeWidth={active ? 2.4 : 1.8} /><span>{item.label}</span>{item.id === 'inventory' && <em>2</em>}</button> }

function PageHeader({ page, onNavigate }: { page: Page; onNavigate: (p: Page) => void }) {
  const info: Record<Page, [string, string]> = { dashboard: ['صباح الخير، طارق 👋', 'إليك ملخص نشاطك اليوم'], pos: ['نقطة البيع', 'أنشئ فاتورة جديدة بسرعة وسهولة'], products: ['المنتجات', 'أدر منتجاتك وأسعارك ومخزونك'], inventory: ['المخزون', 'تابع الكميات وحركات المخزون'], sales: ['المبيعات', 'كل فواتير ومبيعات نشاطك في مكان واحد'], purchases: ['المشتريات', 'تابع التوريدات وفواتير الموردين'], customers: ['العملاء والديون', 'إدارة العملاء وكشوف الحساب'], suppliers: ['الموردون', 'تابع الموردين ومستحقاتهم'], expenses: ['المصروفات', 'سجل وتابع مصروفات نشاطك'], reports: ['التقارير', 'أرقام واضحة تساعدك على اتخاذ القرار'], users: ['المستخدمون والصلاحيات', 'تحكم في وصول فريقك للنظام'], settings: ['الإعدادات', 'خصص Dukkan ليتناسب مع نشاطك'], help: ['مركز المساعدة', 'كل ما تحتاجه لاستخدام Dukkan'] }
  const [title, subtitle] = info[page]
  return <div className="page-header"><div><div className="eyebrow">الرئيسية <span>/</span> {title.replace('، طارق 👋', '')}</div><h1>{title}</h1><p>{subtitle}</p></div>{page === 'dashboard' && <div className="header-actions"><button className="btn secondary"><CalendarDays size={17} /> سبتمبر 2026 <ChevronDown size={14} /></button><button className="btn primary" onClick={() => onNavigate('pos')}><Plus size={18} /> عملية بيع جديدة</button></div>}</div>
}

function Dashboard({ onNavigate }: { onNavigate: (p: Page) => void }) {
  const { products, sales, customers, suppliers, expenses } = useAppStore()
  const low = products.filter((p) => p.trackInventory && p.stock <= p.minStock)
  const todaySales = sales.slice(0, 2).reduce((n, s) => n + s.total, 0)
  return <div className="dashboard">
    <div className="stats-grid">
      <StatCard label="مبيعات اليوم" value={formatMoney(2457800)} change="12.5%" positive icon={TrendingUp} color="blue" />
      <StatCard label="أرباح اليوم" value={formatMoney(468250)} change="8.2%" positive icon={BarChart3} color="gold" />
      <StatCard label="عدد الفواتير" value={formatNumber(24)} change="4.6%" positive icon={ReceiptText} color="purple" />
      <StatCard label="ديون العملاء" value={formatMoney(customers.reduce((n, c) => n + c.balance, 0))} change="2.4%" positive={false} icon={Users} color="red" />
    </div>
    <div className="dashboard-grid"><section className="card chart-card"><div className="card-head"><div><h2>نظرة على المبيعات</h2><span>آخر 7 أيام</span></div><button className="ghost-select">هذا الأسبوع <ChevronDown size={14} /></button></div><SalesChart /></section><section className="card quick-card"><div className="card-head"><div><h2>إجراءات سريعة</h2><span>أنجز مهامك اليومية بسرعة</span></div><Zap size={21} className="gold-icon" /></div><div className="quick-grid"><QuickAction icon={Calculator} label="عملية بيع جديدة" color="blue" onClick={() => onNavigate('pos')} /><QuickAction icon={Package} label="إضافة منتج" color="green" onClick={() => onNavigate('products')} /><QuickAction icon={ClipboardList} label="فاتورة شراء" color="orange" onClick={() => onNavigate('purchases')} /><QuickAction icon={WalletCards} label="تسجيل مصروف" color="purple" onClick={() => onNavigate('expenses')} /></div></section></div>
    <div className="dashboard-grid lower"><section className="card table-card"><div className="card-head"><div><h2>آخر عمليات البيع</h2><span>أحدث الفواتير المسجلة</span></div><button className="link-button" onClick={() => onNavigate('sales')}>عرض الكل <ArrowDownToLine size={15} /></button></div><SalesTable compact /></section><section className="card stock-card"><div className="card-head"><div><h2>تنبيهات المخزون</h2><span>تحتاج إلى متابعة</span></div><button className="link-button" onClick={() => onNavigate('inventory')}>عرض المخزون</button></div>{low.length === 0 ? <EmptyState text="ممتاز! المخزون مستقر" /> : <div className="stock-alerts">{low.slice(0, 3).map((p) => <div className="stock-alert" key={p.id}><div className="product-icon">{p.name.charAt(0)}</div><div className="stock-name"><b>{p.name}</b><span>{p.sku}</span></div><strong className={p.stock === 0 ? 'danger-text' : 'warning-text'}>{p.stock === 0 ? 'نفد المخزون' : `${p.stock} ${p.unit}`}</strong></div>)}</div>}</section></div>
    <div className="mini-insights"><Insight icon={TrendingUp} title="الأكثر مبيعاً" value="زيت النخيل 1 لتر" detail="42 وحدة هذا الأسبوع" /><Insight icon={Truck} title="مستحقات الموردين" value={formatMoney(suppliers.reduce((n, s) => n + s.balance, 0))} detail="على موردين" /><Insight icon={WalletCards} title="مصروفات هذا الشهر" value={formatMoney(expenses.reduce((n, e) => n + e.amount, 0))} detail="في 4 تصنيفات" /><Insight icon={FileText} title="مبيعات اليوم" value={formatMoney(todaySales)} detail="من آخر الفواتير" /></div>
  </div>
}

function StatCard({ label, value, change, positive, icon: Icon, color }: { label: string; value: string; change: string; positive: boolean; icon: Icon; color: string }) { return <div className="stat-card"><div className={`stat-icon ${color}`}><Icon size={20} /></div><div className="stat-content"><span>{label}</span><strong>{value}</strong><small className={positive ? 'up' : 'down'}>{positive ? '↑' : '↓'} {change} <i>مقارنة بالأمس</i></small></div><MoreHorizontal className="stat-more" size={18} /></div> }
function QuickAction({ icon: Icon, label, color, onClick }: { icon: Icon; label: string; color: string; onClick: () => void }) { return <button className="quick-action" onClick={onClick}><span className={`quick-icon ${color}`}><Icon size={20} /></span><b>{label}</b><Plus size={15} /></button> }
function Insight({ icon: Icon, title, value, detail }: { icon: Icon; title: string; value: string; detail: string }) { return <div className="insight"><Icon size={19} /><div><span>{title}</span><b>{value}</b><small>{detail}</small></div></div> }
function SalesChart() { const bars = [42, 58, 51, 76, 62, 90, 68]; const days = ['السبت', 'الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة']; return <div className="chart"><div className="chart-y"><span>3,000</span><span>2,000</span><span>1,000</span><span>0</span></div><div className="bars">{bars.map((h, i) => <div className={`bar-col ${i === 5 ? 'today' : ''}`} key={days[i]}><div className="bar" style={{ height: `${h}%` }}><span>{i === 5 ? '2,458' : ''}</span></div><small>{days[i]}</small></div>)}</div></div> }
function EmptyState({ text }: { text: string }) { return <div className="empty-state"><Sparkles size={21} /><span>{text}</span></div> }
function SalesTable({ compact = false }: { compact?: boolean }) { const sales = useAppStore((s) => s.sales); return <div className="data-table-wrap"><table><thead><tr><th>رقم الفاتورة</th><th>العميل</th><th>التاريخ</th><th>الإجمالي</th><th>الحالة</th>{!compact && <th />}</tr></thead><tbody>{sales.slice(0, compact ? 3 : 20).map((sale) => <tr key={sale.id}><td><b className="invoice-id">{sale.id}</b></td><td>{sale.customer}</td><td className="muted-cell">{sale.date}</td><td><b>{formatMoney(sale.total)}</b></td><td><Status status={sale.status} /></td>{!compact && <td><button className="table-more"><MoreHorizontal size={18} /></button></td>}</tr>)}</tbody></table></div> }
function Status({ status }: { status: string }) { return <span className={`status ${status === 'مدفوعة' ? 'success' : status === 'جزئية' ? 'warning' : 'danger'}`}><i />{status}</span> }

function POS({ notify }: { notify: (m: string) => void }) {
  const { products, customers, completeSale, adjustStock } = useAppStore(); const [query, setQuery] = useState(''); const [cart, setCart] = useState<{ product: Product; qty: number }[]>([]); const [customer, setCustomer] = useState('عميل نقدي'); const [paid, setPaid] = useState(''); const [method, setMethod] = useState('نقدي');
  const filtered = products.filter((p) => `${p.name} ${p.sku} ${p.barcode || ''}`.includes(query)).filter((p) => p.status === 'active'); const subtotal = cart.reduce((n, l) => n + l.product.price * l.qty, 0); const paidMinor = paid ? parseMoney(paid) : subtotal; const remaining = Math.max(subtotal - paidMinor, 0); const add = (product: Product) => setCart((old) => old.find((x) => x.product.id === product.id) ? old.map((x) => x.product.id === product.id ? { ...x, qty: x.qty + 1 } : x) : [...old, { product, qty: 1 }]);
  const checkout = () => { if (!cart.length) return notify('أضف منتجاً إلى السلة أولاً'); if (remaining > 0 && customer === 'عميل نقدي') return notify('اختر عميلاً للفواتير الآجلة'); completeSale(subtotal, paidMinor, customer, cart.reduce((n, x) => n + x.qty, 0)); cart.forEach((x) => adjustStock(x.product.id, x.product.trackInventory ? -x.qty : 0)); setCart([]); setPaid(''); notify('تم حفظ الفاتورة وتحديث المخزون بنجاح'); };
  return <div className="pos-layout"><section className="pos-products"><div className="pos-search-row"><div className="search-box large"><Search size={19} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="ابحث بالاسم أو الباركود أو SKU..." autoFocus /><kbd>F2</kbd></div><button className="btn secondary"><SlidersHorizontal size={17} /> تصفية</button><button className="scan-btn"><span>⌁</span> مسح باركود</button></div><div className="category-chips"><button className="chip selected">الكل <span>{products.length}</span></button>{['مواد غذائية', 'مشروبات', 'منزلية', 'خدمات'].map((c) => <button key={c} className="chip" onClick={() => setQuery(c)}>{c}</button>)}</div><div className="pos-product-grid">{filtered.map((p) => <button className="pos-product" key={p.id} onClick={() => p.stock > 0 || !p.trackInventory ? add(p) : notify('هذا المنتج نافد من المخزون')}><div className={`product-photo tone-${p.id.slice(-1)}`}>{p.name.slice(0, 1)}</div><div className="product-info"><b>{p.name}</b><span>{p.sku}</span><strong>{formatMoney(p.price)}</strong><small className={p.stock <= p.minStock && p.trackInventory ? 'warning-text' : ''}>{p.trackInventory ? `${p.stock} ${p.unit}` : 'خدمة'}</small></div></button>)}</div></section><aside className="cart-panel"><div className="cart-head"><div><h2>الفاتورة الجديدة</h2><span>رقم مؤقت #184</span></div><button className="icon-button" onClick={() => setCart([])}><Trash2 size={18} /></button></div><div className="cart-customer"><label>العميل</label><select value={customer} onChange={(e) => setCustomer(e.target.value)}>{customers.map((c) => <option key={c.id}>{c.name}</option>)}</select></div><div className="cart-lines">{cart.length ? cart.map((line) => <div className="cart-line" key={line.product.id}><div className="cart-line-photo">{line.product.name.slice(0, 1)}</div><div className="cart-line-info"><b>{line.product.name}</b><span>{formatMoney(line.product.price)}</span><div className="qty"><button onClick={() => setCart(cart.map((x) => x.product.id === line.product.id ? { ...x, qty: Math.max(1, x.qty - 1) } : x))}>−</button><b>{line.qty}</b><button onClick={() => add(line.product)}>+</button></div></div><strong>{formatMoney(line.product.price * line.qty)}</strong><button className="remove-line" onClick={() => setCart(cart.filter((x) => x.product.id !== line.product.id))}><X size={14} /></button></div>) : <div className="cart-empty"><div><ShoppingCart size={28} /></div><b>السلة فارغة</b><span>اختر منتجاً من القائمة لإضافته</span></div>}</div><div className="cart-summary"><div><span>المجموع الفرعي</span><b>{formatMoney(subtotal)}</b></div><div><span>الخصم</span><button className="discount-link">إضافة خصم</button></div><div className="total-line"><span>الإجمالي</span><strong>{formatMoney(subtotal)}</strong></div></div><div className="payment-section"><label>طريقة الدفع</label><div className="payment-methods">{['نقدي', 'بطاقة', 'تحويل', 'صك'].map((m) => <button key={m} className={method === m ? 'selected' : ''} onClick={() => setMethod(m)}>{m}</button>)}</div><label>المبلغ المدفوع</label><div className="money-input"><input value={paid} onChange={(e) => setPaid(e.target.value)} placeholder={formatMoney(subtotal).replace(' د.ل', '')} /><span>د.ل</span></div><div className="due-row"><span>المتبقي</span><b className={remaining ? 'danger-text' : 'success-text'}>{formatMoney(remaining)}</b></div><button className="btn primary checkout" onClick={checkout}><ReceiptText size={18} /> حفظ وطباعة الفاتورة <Printer size={17} /></button></div></aside></div>
}

function Products({ notify }: { notify: (m: string) => void }) { const { products, addProduct } = useAppStore(); const [query, setQuery] = useState(''); const [modal, setModal] = useState(false); const filtered = products.filter((p) => `${p.name} ${p.sku} ${p.category}`.includes(query)); return <div className="page-content"><div className="toolbar"><div className="search-box"><Search size={18} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="ابحث عن منتج..." /></div><div className="toolbar-actions"><button className="btn secondary"><Filter size={16} /> تصفية <ChevronDown size={14} /></button><button className="btn primary" onClick={() => setModal(true)}><Plus size={18} /> إضافة منتج</button></div></div><div className="summary-strip"><div><span>إجمالي المنتجات</span><b>{formatNumber(products.length)}</b></div><div><span>منتجات نشطة</span><b className="success-text">{products.filter((p) => p.status === 'active').length}</b></div><div><span>مخزون منخفض</span><b className="warning-text">{products.filter((p) => p.stock <= p.minStock && p.trackInventory && p.stock > 0).length}</b></div><div><span>نافد المخزون</span><b className="danger-text">{products.filter((p) => p.stock === 0 && p.trackInventory).length}</b></div></div><div className="card table-card"><div className="card-head"><div><h2>قائمة المنتجات</h2><span>آخر تحديث منذ لحظات</span></div><button className="icon-button"><MoreHorizontal size={18} /></button></div><div className="data-table-wrap"><table><thead><tr><th>المنتج</th><th>SKU / الباركود</th><th>التصنيف</th><th>سعر البيع</th><th>المخزون</th><th>الحالة</th><th /></tr></thead><tbody>{filtered.map((p) => <tr key={p.id}><td><div className="table-product"><div className={`product-mini tone-${p.id.slice(-1)}`}>{p.name.slice(0, 1)}</div><div><b>{p.name}</b><span>{p.unit}</span></div></div></td><td><b className="invoice-id">{p.sku}</b><small className="barcode">{p.barcode || 'بدون باركود'}</small></td><td>{p.category}</td><td><b>{formatMoney(p.price)}</b><small className="muted-cell">جملة: {formatMoney(p.wholesalePrice)}</small></td><td><div className="stock-cell"><b className={p.stock === 0 ? 'danger-text' : p.stock <= p.minStock ? 'warning-text' : ''}>{p.trackInventory ? p.stock : '∞'}</b><span>{p.trackInventory ? p.unit : 'غير محدود'}</span></div></td><td><Status status={p.status === 'active' ? 'نشط' : 'متوقف'} /></td><td><button className="table-more"><MoreHorizontal size={18} /></button></td></tr>)}</tbody></table></div></div>{modal && <ProductModal onClose={() => setModal(false)} onSave={(data) => { addProduct(data); setModal(false); notify('تمت إضافة المنتج بنجاح') }} />}</div> }

function ProductModal({ onClose, onSave }: { onClose: () => void; onSave: (p: Omit<Product, 'id' | 'sku'> & { sku?: string }) => void }) { const [name, setName] = useState(''); const [price, setPrice] = useState(''); const [cost, setCost] = useState(''); const [stock, setStock] = useState(''); const submit = (e: FormEvent) => { e.preventDefault(); onSave({ name, category: 'أخرى', unit: 'قطعة', cost: parseMoney(cost || '0'), price: parseMoney(price || '0'), wholesalePrice: parseMoney(price || '0'), stock: Number(stock) || 0, minStock: 5, trackInventory: true, status: 'active' }) }; return <Modal title="إضافة منتج جديد" onClose={onClose}><form onSubmit={submit} className="form-grid"><label className="full">اسم المنتج<input required value={name} onChange={(e) => setName(e.target.value)} placeholder="مثال: قهوة عربية 500 جرام" /></label><label>سعر البيع<input required value={price} onChange={(e) => setPrice(e.target.value)} placeholder="0.000" inputMode="decimal" /></label><label>سعر الشراء<input value={cost} onChange={(e) => setCost(e.target.value)} placeholder="0.000" inputMode="decimal" /></label><label>الكمية الافتتاحية<input value={stock} onChange={(e) => setStock(e.target.value)} placeholder="0" inputMode="numeric" /></label><label>الوحدة<select defaultValue="قطعة"><option>قطعة</option><option>كرتونة</option><option>كيس</option><option>كيلوجرام</option><option>خدمة</option></select></label><label className="full">التصنيف<select defaultValue="أخرى"><option>أخرى</option><option>مواد غذائية</option><option>مشروبات</option><option>منزلية</option><option>خدمات</option></select></label><div className="modal-actions full"><button type="button" className="btn secondary" onClick={onClose}>إلغاء</button><button className="btn primary" type="submit"><Check size={17} /> حفظ المنتج</button></div></form></Modal> }

function Inventory({ notify }: { notify: (m: string) => void }) { const { products, adjustStock } = useAppStore(); const [modal, setModal] = useState<Product | null>(null); return <div className="page-content"><div className="toolbar"><div className="search-box"><Search size={18} /><input placeholder="ابحث في المخزون..." /></div><div className="toolbar-actions"><button className="btn secondary"><ArrowDownToLine size={16} /> حركة المخزون</button><button className="btn primary" onClick={() => setModal(products[0])}><Plus size={18} /> تسوية مخزون</button></div></div><div className="inventory-cards"><div className="inventory-card"><span className="ic-dot blue" /><div><b>إجمالي الأصناف</b><strong>{products.filter((p) => p.trackInventory).length}</strong></div></div><div className="inventory-card"><span className="ic-dot green" /><div><b>قيمة المخزون</b><strong>{formatMoney(products.reduce((n, p) => n + p.stock * p.cost, 0))}</strong></div></div><div className="inventory-card"><span className="ic-dot orange" /><div><b>مخزون منخفض</b><strong>{products.filter((p) => p.stock > 0 && p.stock <= p.minStock).length}</strong></div></div><div className="inventory-card"><span className="ic-dot red" /><div><b>نافد المخزون</b><strong>{products.filter((p) => p.stock === 0 && p.trackInventory).length}</strong></div></div></div><div className="card table-card"><div className="card-head"><div><h2>حالة المخزون</h2><span>آخر حركة: اليوم، 10:42 ص</span></div><div className="legend"><span><i className="green-bg" /> جيد</span><span><i className="orange-bg" /> منخفض</span><span><i className="red-bg" /> نافد</span></div></div><div className="data-table-wrap"><table><thead><tr><th>المنتج</th><th>المخزون الحالي</th><th>الحد الأدنى</th><th>الحالة</th><th>قيمة المخزون</th><th /></tr></thead><tbody>{products.filter((p) => p.trackInventory).map((p) => <tr key={p.id}><td><div className="table-product"><div className={`product-mini tone-${p.id.slice(-1)}`}>{p.name.slice(0, 1)}</div><b>{p.name}</b></div></td><td><b>{p.stock} <small>{p.unit}</small></b></td><td>{p.minStock} {p.unit}</td><td><Status status={p.stock === 0 ? 'نافد' : p.stock <= p.minStock ? 'منخفض' : 'جيد'} /></td><td><b>{formatMoney(p.stock * p.cost)}</b></td><td><button className="small-action" onClick={() => setModal(p)}>تسوية</button></td></tr>)}</tbody></table></div></div>{modal && <StockModal product={modal} onClose={() => setModal(null)} onSave={(amount) => { adjustStock(modal.id, amount); setModal(null); notify('تم تحديث المخزون وتسجيل الحركة') }} />}</div> }
function StockModal({ product, onClose, onSave }: { product: Product; onClose: () => void; onSave: (n: number) => void }) { const [amount, setAmount] = useState(''); return <Modal title={`تسوية مخزون — ${product.name}`} onClose={onClose}><div className="stock-modal-copy">الكمية الحالية: <b>{product.stock} {product.unit}</b><span>أدخل كمية الإضافة أو السحب. سيتم تسجيل حركة مخزون جديدة.</span></div><label>التغيير في الكمية<input autoFocus value={amount} onChange={(e) => setAmount(e.target.value)} placeholder="مثال: 10 أو -3" inputMode="numeric" /></label><div className="modal-actions"><button className="btn secondary" onClick={onClose}>إلغاء</button><button className="btn primary" onClick={() => onSave(Number(amount) || 0)}><Check size={17} /> حفظ الحركة</button></div></Modal> }

function Sales() { return <div className="page-content"><div className="toolbar"><div className="search-box"><Search size={18} /><input placeholder="ابحث برقم الفاتورة أو اسم العميل..." /></div><div className="toolbar-actions"><button className="btn secondary"><CalendarDays size={16} /> هذا الشهر <ChevronDown size={14} /></button><button className="btn primary"><Printer size={17} /> طباعة التقرير</button></div></div><div className="summary-strip sales-summary"><div><span>إجمالي المبيعات</span><b>{formatMoney(2457800)}</b></div><div><span>الفواتير</span><b>24</b></div><div><span>مدفوعة</span><b className="success-text">19</b></div><div><span>آجلة / جزئية</span><b className="warning-text">5</b></div></div><div className="card table-card"><div className="card-head"><div><h2>سجل المبيعات</h2><span>سبتمبر 2026</span></div><button className="btn secondary"><ArrowDownToLine size={16} /> تصدير CSV</button></div><SalesTable /></div></div> }

function Purchases({ notify }: { notify: (m: string) => void }) { const suppliers = useAppStore((s) => s.suppliers); const [modal, setModal] = useState(false); return <div className="page-content"><div className="toolbar"><div className="search-box"><Search size={18} /><input placeholder="ابحث برقم الفاتورة أو المورد..." /></div><div className="toolbar-actions"><button className="btn secondary"><Filter size={16} /> تصفية</button><button className="btn primary" onClick={() => setModal(true)}><Plus size={18} /> فاتورة شراء جديدة</button></div></div><div className="summary-strip"><div><span>مشتريات الشهر</span><b>{formatMoney(7840000)}</b></div><div><span>الفواتير</span><b>18</b></div><div><span>مدفوع</span><b className="success-text">{formatMoney(6120000)}</b></div><div><span>مستحق للموردين</span><b className="warning-text">{formatMoney(suppliers.reduce((n, s) => n + s.balance, 0))}</b></div></div><div className="card empty-page"><ClipboardList size={34} /><h2>ابدأ بتسجيل مشترياتك</h2><p>سجّل فاتورة شراء لتحديث المخزون وحساب مستحقات المورد تلقائياً.</p><button className="btn primary" onClick={() => setModal(true)}><Plus size={18} /> تسجيل فاتورة شراء</button></div>{modal && <Modal title="فاتورة شراء جديدة" onClose={() => setModal(false)}><div className="form-grid"><label className="full">المورد<select><option>اختر المورد</option>{suppliers.map((s) => <option key={s.id}>{s.name}</option>)}</select></label><label>رقم الفاتورة<input placeholder="PUR-000019" /></label><label>التاريخ<input type="date" defaultValue="2026-09-11" /></label><label>الإجمالي<input placeholder="0.000" /></label><label>المبلغ المدفوع<input placeholder="0.000" /></label><label className="full">ملاحظات<textarea placeholder="ملاحظات اختيارية" /></label><div className="modal-actions full"><button className="btn secondary" onClick={() => setModal(false)}>إلغاء</button><button className="btn primary" onClick={() => { setModal(false); notify('تم حفظ فاتورة الشراء') }}><Check size={17} /> حفظ الفاتورة</button></div></div></Modal>}</div> }

function Customers({ notify }: { notify: (m: string) => void }) { const { customers, addCustomer } = useAppStore(); const [modal, setModal] = useState(false); const [q, setQ] = useState(''); const filtered = customers.filter((c) => `${c.name} ${c.phone} ${c.city}`.includes(q)); return <div className="page-content"><div className="toolbar"><div className="search-box"><Search size={18} /><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="ابحث عن عميل..." /></div><div className="toolbar-actions"><button className="btn secondary"><FileText size={16} /> كشف حساب</button><button className="btn primary" onClick={() => setModal(true)}><UserPlus size={18} /> إضافة عميل</button></div></div><div className="summary-strip"><div><span>إجمالي العملاء</span><b>{customers.length}</b></div><div><span>إجمالي المشتريات</span><b>{formatMoney(customers.reduce((n, c) => n + c.purchases, 0))}</b></div><div><span>إجمالي الديون</span><b className="danger-text">{formatMoney(customers.reduce((n, c) => n + c.balance, 0))}</b></div><div><span>عملاء نشطون</span><b className="success-text">{customers.length}</b></div></div><div className="card table-card"><div className="card-head"><div><h2>قائمة العملاء</h2><span>كشف حساب ودفعات كل عميل</span></div></div><div className="data-table-wrap"><table><thead><tr><th>العميل</th><th>الهاتف</th><th>المدينة</th><th>إجمالي المشتريات</th><th>الرصيد المستحق</th><th>آخر عملية</th><th /></tr></thead><tbody>{filtered.map((c) => <tr key={c.id}><td><div className="table-product"><div className="avatar customer-avatar">{c.name.slice(0, 1)}</div><b>{c.name}</b></div></td><td>{c.phone}</td><td>{c.city}</td><td><b>{formatMoney(c.purchases)}</b></td><td><b className={c.balance ? 'danger-text' : 'success-text'}>{formatMoney(c.balance)}</b></td><td className="muted-cell">{c.lastPurchase}</td><td><button className="small-action">كشف الحساب</button></td></tr>)}</tbody></table></div></div>{modal && <CustomerModal onClose={() => setModal(false)} onSave={(data) => { addCustomer(data); setModal(false); notify('تمت إضافة العميل بنجاح') }} />}</div> }
function CustomerModal({ onClose, onSave }: { onClose: () => void; onSave: (d: { name: string; phone: string; city: string }) => void }) { const [name, setName] = useState(''); const [phone, setPhone] = useState(''); const [city, setCity] = useState(''); return <Modal title="إضافة عميل جديد" onClose={onClose}><div className="form-grid"><label className="full">اسم العميل<input required value={name} onChange={(e) => setName(e.target.value)} placeholder="الاسم أو اسم المؤسسة" /></label><label>رقم الهاتف<input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="091-0000000" /></label><label>المدينة<input value={city} onChange={(e) => setCity(e.target.value)} placeholder="طرابلس" /></label><label className="full">العنوان<textarea placeholder="العنوان بالتفصيل (اختياري)" /></label><div className="modal-actions full"><button className="btn secondary" onClick={onClose}>إلغاء</button><button className="btn primary" onClick={() => name && onSave({ name, phone, city })}><Check size={17} /> حفظ العميل</button></div></div></Modal> }

function Suppliers() { const suppliers = useAppStore((s) => s.suppliers); return <div className="page-content"><div className="toolbar"><div className="search-box"><Search size={18} /><input placeholder="ابحث عن مورد..." /></div><div className="toolbar-actions"><button className="btn secondary"><FileText size={16} /> كشف حساب</button><button className="btn primary"><Plus size={18} /> إضافة مورد</button></div></div><div className="summary-strip"><div><span>إجمالي الموردين</span><b>{suppliers.length}</b></div><div><span>إجمالي المشتريات</span><b>{formatMoney(suppliers.reduce((n, s) => n + s.purchases, 0))}</b></div><div><span>المستحقات</span><b className="danger-text">{formatMoney(suppliers.reduce((n, s) => n + s.balance, 0))}</b></div><div><span>آخر تحديث</span><b>اليوم</b></div></div><div className="card table-card"><div className="card-head"><div><h2>قائمة الموردين</h2><span>يتم استنتاج المنتجات من سجل المشتريات</span></div></div><div className="data-table-wrap"><table><thead><tr><th>المورد</th><th>رقم المورد</th><th>الهاتف</th><th>المشتريات</th><th>المستحق</th><th>آخر شراء</th><th /></tr></thead><tbody>{suppliers.map((s) => <tr key={s.id}><td><div className="table-product"><div className="avatar supplier-avatar"><Truck size={16} /></div><b>{s.name}</b></div></td><td><b className="invoice-id">SUP-00000{s.id.slice(-1)}</b></td><td>{s.phone}</td><td><b>{formatMoney(s.purchases)}</b></td><td><b className="danger-text">{formatMoney(s.balance)}</b></td><td className="muted-cell">{s.lastPurchase}</td><td><button className="table-more"><MoreHorizontal size={18} /></button></td></tr>)}</tbody></table></div></div></div> }

function Expenses({ notify }: { notify: (m: string) => void }) { const { expenses, addExpense } = useAppStore(); const [modal, setModal] = useState(false); const [amount, setAmount] = useState(''); const [note, setNote] = useState(''); return <div className="page-content"><div className="toolbar"><div className="search-box"><Search size={18} /><input placeholder="ابحث في المصروفات..." /></div><div className="toolbar-actions"><button className="btn secondary"><CalendarDays size={16} /> سبتمبر 2026</button><button className="btn primary" onClick={() => setModal(true)}><Plus size={18} /> تسجيل مصروف</button></div></div><div className="summary-strip"><div><span>مصروفات الشهر</span><b>{formatMoney(expenses.reduce((n, e) => n + e.amount, 0))}</b></div><div><span>عدد المصروفات</span><b>{expenses.length}</b></div><div><span>أعلى تصنيف</span><b>كهرباء</b></div><div><span>متوسط المصروف</span><b>{formatMoney(Math.round(expenses.reduce((n, e) => n + e.amount, 0) / expenses.length))}</b></div></div><div className="card table-card"><div className="card-head"><div><h2>سجل المصروفات</h2><span>سبتمبر 2026</span></div><button className="btn secondary"><ArrowDownToLine size={16} /> تصدير</button></div><div className="data-table-wrap"><table><thead><tr><th>التصنيف</th><th>البيان</th><th>التاريخ</th><th>المبلغ</th><th /></tr></thead><tbody>{expenses.map((e) => <tr key={e.id}><td><span className="category-label"><i />{e.category}</span></td><td>{e.note}</td><td className="muted-cell">{e.date}</td><td><b>{formatMoney(e.amount)}</b></td><td><button className="table-more"><MoreHorizontal size={18} /></button></td></tr>)}</tbody></table></div></div>{modal && <Modal title="تسجيل مصروف" onClose={() => setModal(false)}><div className="form-grid"><label>التصنيف<select><option>إيجار</option><option>كهرباء</option><option>نقل</option><option>صيانة</option><option>رواتب</option><option>اتصالات</option><option>أخرى</option></select></label><label>المبلغ<input autoFocus value={amount} onChange={(e) => setAmount(e.target.value)} placeholder="0.000" /></label><label className="full">البيان<textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="سبب المصروف" /></label><div className="modal-actions full"><button className="btn secondary" onClick={() => setModal(false)}>إلغاء</button><button className="btn primary" onClick={() => { addExpense({ category: 'أخرى', note: note || 'مصروف جديد', amount: parseMoney(amount || '0') }); setModal(false); setAmount(''); setNote(''); notify('تم تسجيل المصروف') }}><Check size={17} /> حفظ المصروف</button></div></div></Modal>}</div> }

function Reports() { const reports = [{ icon: TrendingUp, title: 'تقرير المبيعات', desc: 'ملخص المبيعات حسب الفترة والعميل وطريقة الدفع', color: 'blue' }, { icon: BarChart3, title: 'تقرير الأرباح', desc: 'صافي الربح مع حفظ تكلفة الشراء وقت البيع', color: 'green' }, { icon: Box, title: 'تقرير المخزون', desc: 'قيمة وحركة المخزون والأصناف النافدة', color: 'orange' }, { icon: Users, title: 'ديون العملاء', desc: 'الأرصدة المستحقة وكشوف الحساب', color: 'purple' }, { icon: Truck, title: 'مستحقات الموردين', desc: 'المشتريات والدفعات والأرصدة', color: 'red' }, { icon: WalletCards, title: 'تقرير المصروفات', desc: 'المصروفات حسب التصنيف والفترة', color: 'gold' }]; return <div className="page-content"><div className="report-toolbar"><div><h2>تقارير النشاط</h2><p>اختر التقرير والفترة الزمنية المناسبة</p></div><div className="toolbar-actions"><button className="btn secondary"><CalendarDays size={16} /> من 01 سبتمبر إلى 11 سبتمبر <ChevronDown size={14} /></button><button className="btn primary"><Printer size={17} /> طباعة</button></div></div><div className="report-grid">{reports.map((r) => { const Icon = r.icon; return <button className="report-card" key={r.title}><span className={`report-icon ${r.color}`}><Icon size={22} /></span><div><h3>{r.title}</h3><p>{r.desc}</p></div><ArrowDownToLine size={17} /></button> })}</div><div className="card report-preview"><div className="card-head"><div><h2>ملخص الأداء</h2><span>01 — 11 سبتمبر 2026</span></div><button className="btn secondary"><ArrowDownToLine size={16} /> تصدير Excel</button></div><div className="report-metrics"><div><span>إجمالي المبيعات</span><b>{formatMoney(15480700)}</b><small className="up">↑ 18.4%</small></div><div><span>تكلفة البضاعة</span><b>{formatMoney(10824600)}</b><small>من المبيعات</small></div><div><span>صافي الربح</span><b className="success-text">{formatMoney(4656100)}</b><small className="up">↑ 11.2%</small></div><div><span>هامش الربح</span><b>30.1%</b><small>ممتاز</small></div></div></div></div> }

function UsersPage() { return <div className="page-content"><div className="toolbar"><div className="search-box"><Search size={18} /><input placeholder="ابحث عن مستخدم..." /></div><button className="btn primary"><UserPlus size={18} /> إضافة مستخدم</button></div><div className="card permissions-card"><div className="card-head"><div><h2>المستخدمون</h2><span>أدر صلاحيات الوصول إلى Dukkan</span></div></div><div className="user-row"><div className="avatar">ط</div><div className="user-details"><b>طارق العمامي</b><span>طارق • آخر دخول: الآن</span></div><span className="role admin">مدير النظام</span><span className="status success"><i /> نشط</span><button className="table-more"><MoreHorizontal size={18} /></button></div><div className="user-row"><div className="avatar cash">م</div><div className="user-details"><b>محمد سالم</b><span>m.salem • آخر دخول: أمس</span></div><span className="role">كاشير</span><span className="status success"><i /> نشط</span><button className="table-more"><MoreHorizontal size={18} /></button></div></div><div className="card role-card"><div className="card-head"><div><h2>الأدوار الافتراضية</h2><span>يمكن توسيع الصلاحيات لاحقاً</span></div></div><div className="role-list"><div><ShieldCheck size={20} /><b>مدير النظام</b><span>وصول كامل لكل أجزاء النظام والنسخ الاحتياطي</span></div><div><Calculator size={20} /><b>كاشير</b><span>نقطة البيع، المبيعات، العملاء ودفعات العملاء</span></div></div></div></div> }

function SettingsPage({ notify }: { notify: (m: string) => void }) {
  const { business, updateBusiness } = useAppStore()
  const [name, setName] = useState(business.name)
  const [lastBackup, setLastBackup] = useState('لم تُنشأ نسخة بعد')
  const fileInput = useRef<HTMLInputElement>(null)

  const createBackup = () => {
    const state = useAppStore.getState()
    const payload = {
      format: 'Dukkan Backup',
      version: 1,
      exportedAt: new Date().toISOString(),
      data: {
        setupComplete: state.setupComplete,
        business: state.business,
        products: state.products,
        customers: state.customers,
        suppliers: state.suppliers,
        sales: state.sales,
        expenses: state.expenses,
        categories: state.categories,
        activeUser: state.activeUser,
      },
    }
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `Dukkan-Backup-${new Date().toISOString().slice(0, 10)}.json`
    link.click()
    URL.revokeObjectURL(url)
    setLastBackup('الآن')
    notify('تم تنزيل النسخة الاحتياطية بنجاح')
  }

  const restoreBackup = async (file?: File) => {
    if (!file) return
    try {
      const parsed = JSON.parse(await file.text()) as { format?: unknown; data?: Record<string, unknown> }
      const data = parsed.data
      if (parsed.format !== 'Dukkan Backup' || !data || typeof data.business !== 'object' || !Array.isArray(data.products) || !Array.isArray(data.customers) || !Array.isArray(data.suppliers) || !Array.isArray(data.sales) || !Array.isArray(data.expenses) || !Array.isArray(data.categories)) {
        throw new Error('invalid-backup')
      }
      useAppStore.setState({
        setupComplete: Boolean(data.setupComplete),
        business: data.business as Business,
        products: data.products as Product[],
        customers: data.customers as ReturnType<typeof useAppStore.getState>['customers'],
        suppliers: data.suppliers as ReturnType<typeof useAppStore.getState>['suppliers'],
        sales: data.sales as ReturnType<typeof useAppStore.getState>['sales'],
        expenses: data.expenses as ReturnType<typeof useAppStore.getState>['expenses'],
        categories: data.categories as string[],
        activeUser: typeof data.activeUser === 'string' ? data.activeUser : 'مدير النظام',
      })
      notify('تم استرجاع البيانات، سيتم تحديث الواجهة')
      window.setTimeout(() => window.location.reload(), 700)
    } catch {
      notify('ملف النسخة الاحتياطية غير صالح')
    } finally {
      if (fileInput.current) fileInput.current.value = ''
    }
  }

  return <div className="page-content settings-page"><div className="settings-layout"><aside className="settings-nav"><button className="selected"><Store size={17} /> بيانات النشاط</button><button><Palette size={17} /> الهوية والمظهر</button><button><SlidersHorizontal size={17} /> إعدادات النظام</button><button><DatabaseBackup size={17} /> النسخ الاحتياطي</button></aside><div className="settings-main"><section className="card settings-card"><div className="card-head"><div><h2>بيانات النشاط</h2><span>تظهر هذه البيانات على الفواتير والتقارير</span></div><button className="btn primary" onClick={() => { updateBusiness({ name }); notify('تم حفظ إعدادات النشاط') }}><Check size={17} /> حفظ التغييرات</button></div><div className="form-grid"><label className="full">اسم النشاط<input value={name} onChange={(e) => setName(e.target.value)} /></label><label>نوع النشاط<select defaultValue={business.type}><option>متجر تجزئة</option><option>جملة وتجزئة</option><option>مطعم ومقهى</option><option>خدمات</option></select></label><label>رقم الهاتف<input defaultValue={business.phone} /></label><label className="full">العنوان<input defaultValue={business.address} /></label><label className="full">الرقم الضريبي <small className="optional">اختياري</small><input defaultValue={business.taxNumber} placeholder="يمكن تركه فارغاً" /></label></div></section><section className="card settings-card"><div className="card-head"><div><h2>العملة واللغة</h2><span>الإعدادات المحلية لنشاطك</span></div></div><div className="settings-options"><div><b>العملة</b><span>الدينار الليبي (LYD)</span></div><div><b>الخانات العشرية</b><span>3 خانات — 1,250.000</span></div><div><b>لغة الواجهة</b><span>العربية — RTL</span></div></div></section><section className="card settings-card"><div className="card-head"><div><h2>النسخ الاحتياطي</h2><span>بياناتك محفوظة محلياً على هذا الجهاز</span></div></div><div className="backup-row"><div className="backup-symbol"><DatabaseBackup size={24} /></div><div><b>أنشئ نسخة احتياطية الآن</b><span>آخر نسخة احتياطية: {lastBackup}</span></div><button className="btn secondary" onClick={createBackup}><DatabaseBackup size={16} /> إنشاء نسخة</button><button className="btn secondary" onClick={() => fileInput.current?.click()}><ArrowUpFromLine size={16} /> استرجاع</button><input ref={fileInput} type="file" accept="application/json,.json" hidden onChange={(e) => void restoreBackup(e.target.files?.[0])} /></div></section></div></div></div>
}

const helpArticles = [{ title: 'البدء السريع', text: 'أدخل بيانات النشاط، أضف التصنيفات والمنتجات، ثم أدخل المخزون الافتتاحي وابدأ أول عملية بيع.' }, { title: 'نقطة البيع', text: 'ابحث عن المنتج بالاسم أو SKU أو امسح الباركود. أضف المنتجات للسلة، اختر العميل وطريقة الدفع ثم احفظ الفاتورة.' }, { title: 'البيع الآجل والديون', text: 'لإنشاء بيع آجل اختر عميلاً وأدخل المبلغ المدفوع. سيظهر المتبقي تلقائياً في كشف حساب العميل.' }, { title: 'المخزون', text: 'كل تغيير في المخزون يُسجل كحركة. استخدم تسوية المخزون للإضافة أو السحب مع توضيح السبب.' }, { title: 'النسخ الاحتياطي', text: 'من الإعدادات أنشئ نسخة محلية من قاعدة البيانات. احتفظ بها في مكان آمن واسترجعها على تثبيت جديد.' }];
function Help() { const [q, setQ] = useState(''); const list = helpArticles.filter((a) => `${a.title} ${a.text}`.includes(q)); return <div className="page-content help-page"><div className="help-hero"><div><span className="help-kicker"><HelpCircle size={17} /> مساعدة تعمل بدون إنترنت</span><h2>كيف نساعدك اليوم؟</h2><p>ابحث في دليل الاستخدام أو اختر موضوعاً للبدء.</p></div><div className="help-search"><Search size={19} /><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="ابحث في دليل الاستخدام..." /></div></div><div className="help-columns"><aside className="help-topics"><b>دليل الاستخدام</b>{['البدء السريع', 'إعداد النشاط', 'المنتجات', 'المخزون', 'نقطة البيع', 'العملاء والديون', 'الموردون والمشتريات', 'التقارير', 'النسخ الاحتياطي', 'الأسئلة الشائعة'].map((x, i) => <button className={i === 0 ? 'active' : ''} key={x}>{x}</button>)}</aside><section className="help-articles"><div className="section-title"><div><h2>{q ? 'نتائج البحث' : 'ابدأ من هنا'}</h2><span>{q ? `${list.length} مقالات مطابقة` : 'كل ما تحتاجه لتشغيل نشاطك يومياً'}</span></div></div>{list.map((a, i) => <article className="help-article" key={a.title}><div className="article-number">{String(i + 1).padStart(2, '0')}</div><div><h3>{a.title}</h3><p>{a.text}</p><button className="link-button">قراءة المقال <ArrowDownToLine size={14} /></button></div></article>)}<div className="about-card"><div className="brand-mark small-mark"><ScaleIcon /></div><div><b>حول Dukkan</b><p>نظام إدارة أعمال محلي مصمم لأصحاب الأعمال في ليبيا.</p><span>إعداد وتطوير المشروع: <strong>طارق العمامي</strong> • إصدار التطوير 0.1.0</span><a href="https://github.com/Elomami1976/Dukkan" target="_blank" rel="noreferrer">المستودع الرسمي على GitHub</a></div></div></section></div></div> }

function SetupWizard() {
  const { completeSetup } = useAppStore(); const [step, setStep] = useState(1); const [business, setBusiness] = useState<Business>({ name: '', type: 'متجر تجزئة', phone: '', address: '', taxNumber: '', logo: '', primaryColor: '#d99a2b', currency: 'الدينار الليبي' }); const [user, setUser] = useState({ name: 'طارق العمامي', username: 'admin', password: '', confirm: '' }); const update = (key: keyof Business, value: string) => setBusiness((b) => ({ ...b, [key]: value })); const next = () => setStep((s) => Math.min(4, s + 1)); const finish = () => completeSetup({ ...business, name: business.name || 'متجر البركة' }, user.name || 'المدير');
  return <div className="setup-page" dir="rtl"><div className="setup-sidebar"><div className="setup-brand"><div className="brand-mark"><ScaleIcon /></div><span>Dukkan</span></div><div className="setup-side-copy"><span>ابدأ بتنظيم نشاطك</span><h2>كل شيء في مكان واحد.</h2><p>مبيعاتك، مخزونك، عملاؤك وتقاريرك — إدارة بسيطة تناسب يومك.</p></div><div className="setup-quote"><span>“</span><p>صُمم لأصحاب الأعمال في ليبيا، ويعمل معك حتى بدون إنترنت.</p></div><div className="setup-side-footer">نسخة محلية وآمنة <span>•</span> v0.1.0</div></div><div className="setup-content"><div className="setup-top"><span>إعداد النشاط</span><span>الخطوة {step} من 4</span></div><div className="setup-progress"><i style={{ width: `${step * 25}%` }} /></div><div className="setup-form">{step === 1 && <><span className="step-kicker">الخطوة الأولى</span><h1>أخبرنا عن نشاطك</h1><p>هذه المعلومات ستظهر في الفواتير والتقارير الخاصة بك.</p><div className="form-grid setup-grid"><label className="full">اسم النشاط<input autoFocus value={business.name} onChange={(e) => update('name', e.target.value)} placeholder="مثال: متجر البركة" /></label><label>نوع النشاط<select value={business.type} onChange={(e) => update('type', e.target.value)}><option>متجر تجزئة</option><option>جملة وتجزئة</option><option>مطعم ومقهى</option><option>خدمات</option></select></label><label>رقم الهاتف<input value={business.phone} onChange={(e) => update('phone', e.target.value)} placeholder="091-0000000" /></label><label className="full">العنوان<input value={business.address} onChange={(e) => update('address', e.target.value)} placeholder="المدينة، المنطقة، الشارع" /></label><label className="full">الرقم الضريبي <small className="optional">اختياري</small><input value={business.taxNumber} onChange={(e) => update('taxNumber', e.target.value)} placeholder="يمكنك إضافته لاحقاً" /></label></div></>}{step === 2 && <><span className="step-kicker">الخطوة الثانية</span><h1>اجعل Dukkan يشبه نشاطك</h1><p>اختر لونك الرئيسي وأضف شعار نشاطك إن وجد.</p><div className="identity-preview"><div className="preview-sidebar"><div className="preview-logo"><ScaleIcon /></div><span>{business.name || 'اسم نشاطك'}</span><small>لوحة التحكم</small><small>نقطة البيع</small><small>المنتجات</small></div><div className="preview-content"><div className="preview-topline" /><h3>صباح الخير 👋</h3><div className="preview-cards"><i /><i /><i /></div></div></div><div className="color-row"><label>اللون الرئيسي<div className="color-options">{['#d99a2b', '#2563eb', '#16a34a', '#7c3aed', '#dc2626'].map((c) => <button type="button" key={c} style={{ background: c }} className={business.primaryColor === c ? 'picked' : ''} onClick={() => update('primaryColor', c)} />)}</div></label><label>شعار النشاط <button type="button" className="upload-box"><ArrowUpFromLine size={17} /> رفع الشعار</button></label></div></>}{step === 3 && <><span className="step-kicker">الخطوة الثالثة</span><h1>إعدادات النظام</h1><p>يمكنك تغيير هذه الإعدادات لاحقاً من صفحة الإعدادات.</p><div className="system-settings"><div><span className="setting-leading">د.ل</span><div><b>العملة</b><small>الدينار الليبي (LYD)</small></div><Check size={18} className="setting-check" /></div><div><span className="setting-leading">.000</span><div><b>الخانات العشرية</b><small>ثلاث خانات عشرية — 1,250.000</small></div><Check size={18} className="setting-check" /></div><div><span className="setting-leading">ع</span><div><b>لغة الواجهة</b><small>العربية • اتجاه من اليمين إلى اليسار</small></div><Check size={18} className="setting-check" /></div></div><div className="info-note"><Sparkles size={18} /><span>يستخدم Dukkan أرقاماً صحيحة لحفظ الأموال بدقة، لذلك لن تفقد أي جزء من الدينار.</span></div></>}{step === 4 && <><span className="step-kicker">الخطوة الرابعة والأخيرة</span><h1>أنشئ حساب المدير</h1><p>استخدم هذا الحساب لتسجيل الدخول وإدارة إعدادات النشاط.</p><div className="form-grid setup-grid"><label className="full">اسم المستخدم<input value={user.username} onChange={(e) => setUser({ ...user, username: e.target.value })} /></label><label className="full">الاسم الظاهر<input value={user.name} onChange={(e) => setUser({ ...user, name: e.target.value })} /></label><label>كلمة المرور<input type="password" value={user.password} onChange={(e) => setUser({ ...user, password: e.target.value })} placeholder="••••••••" /></label><label>تأكيد كلمة المرور<input type="password" value={user.confirm} onChange={(e) => setUser({ ...user, confirm: e.target.value })} placeholder="••••••••" /></label></div><div className="security-note"><ShieldCheck size={19} /><span>يتم تخزين كلمة المرور بشكل مشفر وآمن على جهازك فقط.</span></div></>}</div><div className="setup-actions"><button className="btn text-btn" onClick={() => step > 1 && setStep(step - 1)}>{step > 1 ? 'رجوع' : ''}</button><button className="btn primary setup-next" onClick={step === 4 ? finish : next}>{step === 4 ? 'ابدأ باستخدام Dukkan' : 'متابعة'} <ArrowDownToLine size={17} /></button></div><div className="setup-help">تحتاج مساعدة؟ <span>دليل الاستخدام يعمل بدون إنترنت</span></div></div></div>
}

function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) { return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal" onMouseDown={(e) => e.stopPropagation()}><div className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={onClose}><X size={18} /></button></div>{children}</div></div> }

export default App
